content.text:
Brief:
Un labyrinthe de haies vu du dessus, joué au tour par tour. Le joueur guide un hérisson case par case en glissant le doigt vers une direction. Chaque déplacement coûte un pas, et des pommes posées dans les allées rapportent des points. La partie est gagnée quand le hérisson atteint la sortie, et elle est bloquée si plus aucun pas ne reste. Aucun chronomètre ne presse le joueur.

Plan:
{"gameType":"puzzle-board","input":"swipe-lanes","lang":"fr","loop":"Glissez le doigt pour guider le hérisson case par case dans les haies et ramasser des pommes. Atteignez la sortie avant d'épuiser vos pas, sinon la partie est bloquée.","slug":"le-labyrinthe-du-herisson","style":"paper-cut","title":"Le Labyrinthe du Hérisson"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Labyrinthe du Hérisson</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     overflow: hidden;
14|     background: #f4ecd8;
15|     touch-action: none;
16|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17|   }
18|   #game {
19|     display: block;
20|     width: 100vw;
21|     height: 100dvh;
22|     background: #f4ecd8;
23|   }
24|   #hint {
25|     position: fixed;
26|     left: 0; right: 0; bottom: 8px;
27|     text-align: center;
28|     color: #3d405b;
29|     font-size: 14px;
30|     pointer-events: none;
31|     user-select: none;
32|   }
33| </style>
34| </head>
35| <body>
36| <canvas id="game"></canvas>
37| <div id="hint"></div>
38| <script>
39| // ---- Bridge helper (verbatim) ----
40| const CARTRIDGE = {
41|   send(type, payload = {}) {
42|     window.parent.postMessage(
43|       { source: "cartridge", v: 1, type, payload },
44|       "*",
45|     );
46|   },
47| };
48| </script>
49| <script>
50| (function(){
51|   "use strict";
52| 
53|   const canvas = document.getElementById("game");
54|   const ctx = canvas.getContext("2d");
55|   const hintEl = document.getElementById("hint");
56| 
57|   const PALETTE = {
58|     bg: "#f4ecd8",
59|     layer: "#e07a5f",
60|     accent: "#3d405b",
61|     highlight: "#81b29a"
62|   };
63| 
64|   let dpr = Math.max(1, window.devicePixelRatio || 1);
65|   let W = 0, H = 0;
66| 
67|   // ---- Seeded jitter for paper-cut look ----
68|   function mulberry32(seed) {
69|     return function() {
70|       seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
71|       let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
72|       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
73|       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
74|     };
75|   }
76|   const rng = mulberry32(1337);
77|   const jitterCache = new Map();
78|   function jitterFor(key, n) {
79|     if (jitterCache.has(key)) return jitterCache.get(key);
80|     const arr = [];
81|     for (let i = 0; i < n; i++) {
82|       arr.push((rng() - 0.5) * 3);
83|     }
84|     jitterCache.set(key, arr);
85|     return arr;
86|   }
87| 
88|   function jitteredRoundRect(x, y, w, h, r, key) {
89|     // returns path with jittered corners
90|     const pts = [
91|       [x + r, y], [x + w - r, y], [x + w, y], [x + w, y + r],
92|       [x + w, y + h - r], [x + w, y + h], [x + w - r, y + h],
93|       [x + r, y + h], [x, y + h], [x, y + h - r],
94|       [x, y + r], [x, y]
95|     ];
96|     const j = jitterFor(key, pts.length * 2);
97|     const p = new Path2D();
98|     p.moveTo(x + r + j[0], y + j[1]);
99|     p.lineTo(x + w - r + j[2], y + j[3]);
100|     p.quadraticCurveTo(x + w + j[4], y + j[5], x + w + j[6], y + r + j[7]);
101|     p.lineTo(x + w + j[8], y + h - r + j[9]);
102|     p.quadraticCurveTo(x + w + j[10], y + h + j[11], x + w - r + j[12], y + h + j[13]);
103|     p.lineTo(x + r + j[14], y + h + j[15]);
104|     p.quadraticCurveTo(x + j[16], y + h + j[17], x + j[18], y + h - r + j[19]);
105|     p.lineTo(x + j[20], y + r + j[21]);
106|     p.quadraticCurveTo(x + j[22], y + j[23], x + r + j[0], y + j[1]);
107|     p.closePath();
108|     return p;
109|   }
110| 
111|   function drawPlate(x, y, w, h, r, fill, key, shadow) {
112|     ctx.save();
113|     if (shadow !== false) {
114|       ctx.shadowColor = "rgba(61,64,91,0.35)";
115|       ctx.shadowBlur = 6;
116|       ctx.shadowOffsetY = 3;
117|     }
118|     const path = jitteredRoundRect(x, y, w, h, r, key);
119|     ctx.fillStyle = fill;
120|     ctx.fill(path);
121|     ctx.restore();
122|   }
123| 
124|   // ---- Game state ----
125|   const GRID = 7; // 7x7 board
126|   let cell = [];
127|   let hedgehog = { x: 0, y: 0 };
128|   let exitPos = { x: 0, y: 0 };
129|   let apples = [];
130|   let hedges = new Set();
131|   let score = 0;
132|   let stepsLeft = 0;
133|   let maxSteps = 0;
134|   let moves = 0;
135|   let level = 1;
136| 
137|   let state = "title"; // title, playing, ended
138|   let paused = false;
139|   let endReason = null;
140|   let started = false;
141| 
142|   function key(x, y) { return x + "," + y; }
143| 
144|   function buildLevel(idx) {
145|     hedges = new Set();
146|     apples = [];
147|     hedgehog = { x: 0, y: 0 };
148|     exitPos = { x: GRID - 1, y: GRID - 1 };
149|     score = 0;
150|     moves = 0;
151|     endReason = null;
152| 
153|     const rng2 = mulberry32(1000 + idx * 77);
154|     // place some hedges avoiding start and exit, ensure not fully blocking path via simple heuristic
155|     const hedgeCount = 8 + idx * 2;
156|     let placed = 0;
157|     let attempts = 0;
158|     while (placed < hedgeCount && attempts < 500) {
159|       attempts++;
160|       const hx = Math.floor(rng2() * GRID);
161|       const hy = Math.floor(rng2() * GRID);
162|       if ((hx === 0 && hy === 0) || (hx === exitPos.x && hy === exitPos.y)) continue;
163|       const k = key(hx, hy);
164|       if (hedges.has(k)) continue;
165|       hedges.add(k);
166|       placed++;
167|     }
168|     // ensure path exists via BFS; if not, remove random hedges until path found
169|     function pathExists() {
170|       const visited = new Set();
171|       const queue = [[0,0]];
172|       visited.add(key(0,0));
173|       while (queue.length) {
174|         const [cx, cy] = queue.shift();
175|         if (cx === exitPos.x && cy === exitPos.y) return true;
176|         const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
177|         for (const [dx,dy] of dirs) {
178|           const nx = cx+dx, ny = cy+dy;
179|           if (nx<0||ny<0||nx>=GRID||ny>=GRID) continue;
180|           const nk = key(nx,ny);
181|           if (visited.has(nk) || hedges.has(nk)) continue;
182|           visited.add(nk);
183|           queue.push([nx,ny]);
184|         }
185|       }
186|       return false;
187|     }
188|     let guard = 0;
189|     while (!pathExists() && guard < 1000) {
190|       guard++;
191|       const arr = Array.from(hedges);
192|       if (arr.length === 0) break;
193|       const removeIdx = Math.floor(rng2() * arr.length);
194|       hedges.delete(arr[removeIdx]);
195|     }
196| 
197|     // place apples on free cells reachable, not on start/exit/hedge
198|     const appleCount = 4;
199|     let ap = 0;
200|     attempts = 0;
201|     while (ap < appleCount && attempts < 500) {
202|       attempts++;
203|       const ax = Math.floor(rng2() * GRID);
204|       const ay = Math.floor(rng2() * GRID);
205|       if ((ax===0 && ay===0) || (ax===exitPos.x && ay===exitPos.y)) continue;
206|       const k = key(ax,ay);
207|       if (hedges.has(k)) continue;
208|       if (apples.some(a => a.x===ax && a.y===ay)) continue;
209|       apples.push({ x: ax, y: ay, collected: false });
210|       ap++;
211|     }
212| 
213|     maxSteps = GRID * 2 + 6 + idx * 2;
214|     stepsLeft = maxSteps;
215|   }
216| 
217|   function resetGameState() {
218|     level = 1;
219|     buildLevel(level);
220|   }
221| 
222|   function backToTitle() {
223|     state = "title";
224|     started = false;
225|     paused = false;
226|     draw();
227|   }
228| 
229|   function startGame() {
230|     state = "playing";
231|     started = true;
232|     resetGameState();
233|     CARTRIDGE.send("start");
234|     CARTRIDGE.send("level", { index: level });
235|     CARTRIDGE.send("score", { value: score });
236|     draw();
237|   }
238| 
239|   function isLegalMove(dx, dy) {
240|     const nx = hedgehog.x + dx;
241|     const ny = hedgehog.y + dy;
242|     if (nx < 0 || ny < 0 || nx >= GRID || ny >= GRID) return false;
243|     if (hedges.has(key(nx, ny))) return false;
244|     return true;
245|   }
246| 
247|   function anyLegalMove() {
248|     const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
249|     for (const [dx,dy] of dirs) {
250|       if (isLegalMove(dx,dy)) return true;
251|     }
252|     return false;
253|   }
254| 
255|   function tryMove(dx, dy) {
256|     if (state !== "playing" || paused) return;
257|     if (!isLegalMove(dx, dy)) return;
258|     if (stepsLeft <= 0) return;
259| 
260|     hedgehog.x += dx;
261|     hedgehog.y += dy;
262|     stepsLeft -= 1;
263|     moves += 1;
264| 
265|     let scored = false;
266|     for (const a of apples) {
267|       if (!a.collected && a.x === hedgehog.x && a.y === hedgehog.y) {
268|         a.collected = true;
269|         score += 10;
270|         scored = true;
271|       }
272|     }
273|     if (scored) {
274|       CARTRIDGE.send("score", { value: score });
275|     }
276| 
277|     const wonLevel = (hedgehog.x === exitPos.x && hedgehog.y === exitPos.y);
278| 
279|     if (wonLevel) {
280|       score += 25;
281|       CARTRIDGE.send("score", { value: score });
282|       state = "ended";
283|       endReason = "win";
284|       CARTRIDGE.send("end", { reason: "win", value: score });
285|     } else if (stepsLeft <= 0 || !anyLegalMove()) {
286|       state = "ended";
287|       endReason = "stuck";
288|       CARTRIDGE.send("end", { reason: "stuck", value: score });
289|     }
290| 
291|     draw();
292|   }
293| 
294|   // ---- Input: swipe lanes style (4-directional swipe) ----
295|   const SWIPE_FRACTION = 0.08;
296|   let pressX = 0, pressY = 0;
297|   let pressActive = false;
298| 
299|   canvas.addEventListener("pointerdown", (event) => {
300|     pressX = event.clientX;
301|     pressY = event.clientY;
302|     pressActive = true;
303|     if (state === "title") {
304|       startGame();
305|     } else if (state === "ended") {
306|       // soft reset: go back to title on tap
307|       backToTitle();
308|     }
309|   });
310| 
311|   canvas.addEventListener("pointerup", (event) => {
312|     if (!pressActive) return;
313|     pressActive = false;
314|     if (state !== "playing") return;
315|     const dx = event.clientX - pressX;
316|     const dy = event.clientY - pressY;
317|     const minSwipe = canvas.clientWidth * SWIPE_FRACTION;
318|     if (Math.abs(dx) < minSwipe && Math.abs(dy) < minSwipe) return;
319| 
320|     if (Math.abs(dx) > Math.abs(dy)) {
321|       tryMove(Math.sign(dx), 0);
322|     } else {
323|       tryMove(0, Math.sign(dy));
324|     }
325|   });
326| 
327|   window.addEventListener("keydown", (event) => {
328|     if (state === "title") {
329|       if (event.key === "Enter" || event.key === " ") startGame();
330|       return;
331|     }
332|     if (state === "ended") {
333|       if (event.key === "Enter" || event.key === " ") backToTitle();
334|       return;
335|     }
336|     if (state !== "playing" || paused) return;
337|     if (event.key === "ArrowLeft") tryMove(-1, 0);
338|     else if (event.key === "ArrowRight") tryMove(1, 0);
339|     else if (event.key === "ArrowUp") tryMove(0, -1);
340|     else if (event.key === "ArrowDown") tryMove(0, 1);
341|   });
342| 
343|   // ---- Host bridge messages ----
344|   window.addEventListener("message", (event) => {
345|     const data = event.data;
346|     if (!data || data.source !== "cartridge-host") return;
347|     if (data.type === "pause") paused = true;
348|     if (data.type === "resume") paused = false;
349|     if (data.type === "reset") backToTitle();
350|   });
351| 
352|   // ---- Rendering ----
353|   function resize() {
354|     dpr = Math.max(1, window.devicePixelRatio || 1);
355|     W = window.innerWidth;
356|     H = window.innerHeight;
357|     canvas.width = Math.floor(W * dpr);
358|     canvas.height = Math.floor(H * dpr);
359|     canvas.style.width = W + "px";
360|     canvas.style.height = H + "px";
361|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
362|     draw();
363|   }
364|   window.addEventListener("resize", resize);
365| 
366|   function boardMetrics() {
367|     const margin = Math.min(W, H) * 0.06;
368|     const topArea = Math.min(H * 0.14, 90);
369|     const availW = W - margin * 2;
370|     const availH = H - margin * 2 - topArea;
371|     const size = Math.min(availW, availH);
372|     const cellSize = size / GRID;
373|     const bx = (W - size) / 2;
374|     const by = topArea + (availH - size) / 2 + margin * 0.5;
375|     return { bx, by, cellSize, size };
376|   }
377| 
378|   function drawHedgehog(cx, cy, r) {
379|     ctx.save();
380|     ctx.shadowColor = "rgba(61,64,91,0.35)";
381|     ctx.shadowBlur = 6;
382|     ctx.shadowOffsetY = 3;
383|     // body
384|     ctx.fillStyle = PALETTE.accent;
385|     ctx.beginPath();
386|     ctx.ellipse(cx, cy, r * 0.9, r * 0.7, 0, 0, Math.PI * 2);
387|     ctx.fill();
388|     ctx.restore();
389|     // spikes
390|     ctx.fillStyle = PALETTE.layer;
391|     for (let i = -3; i <= 3; i++) {
392|       const angle = (i / 6) * Math.PI * 0.9 - Math.PI * 0.05;
393|       const sx = cx - Math.cos(angle) * r * 0.3;
394|       const sy = cy - r * 0.5 + Math.sin(angle) * r * 0.2;
395|       ctx.beginPath();
396|       ctx.moveTo(sx, sy);
397|       ctx.lineTo(sx - r * 0.18, sy - r * 0.5);
398|       ctx.lineTo(sx + r * 0.18, sy - r * 0.5);
399|       ctx.closePath();
400|       ctx.fill();
401|     }
402|     // face
403|     ctx.fillStyle = PALETTE.bg;
404|     ctx.beginPath();
405|     ctx.ellipse(cx + r * 0.55, cy + r * 0.1, r * 0.28, r * 0.22, 0, 0, Math.PI * 2);
406|     ctx.fill();
407|     ctx.fillStyle = PALETTE.accent;
408|     ctx.beginPath();
409|     ctx.arc(cx + r * 0.75, cy + r * 0.08, r * 0.05, 0, Math.PI * 2);
410|     ctx.fill();
411|   }
412| 
413|   function drawApple(cx, cy, r) {
414|     ctx.save();
415|     ctx.shadowColor = "rgba(61,64,91,0.3)";
416|     ctx.shadowBlur = 4;
417|     ctx.shadowOffsetY = 2;
418|     ctx.fillStyle = PALETTE.highlight;
419|     ctx.beginPath();
420|     ctx.arc(cx, cy, r * 0.45, 0, Math.PI * 2);
421|     ctx.fill();
422|     ctx.restore();
423|     ctx.fillStyle = PALETTE.accent;
424|     ctx.fillRect(cx - r * 0.03, cy - r * 0.62, r * 0.06, r * 0.2);
425|   }
426| 
427|   function drawHedge(x, y, cellSize, k) {
428|     const px = x, py = y;
429|     drawPlate(px + 2, py + 2, cellSize - 4, cellSize - 4, 8, PALETTE.layer, "hedge" + k, true);
430|     ctx.save();
431|     ctx.strokeStyle = PALETTE.accent;
432|     ctx.lineWidth = 1.2;
433|     ctx.globalAlpha = 0.35;
434|     for (let i = 0; i < 3; i++) {
435|       ctx.beginPath();
436|       ctx.arc(px + cellSize * (0.3 + i * 0.2), py + cellSize * 0.4, cellSize * 0.18, 0, Math.PI * 2);
437|       ctx.stroke();
438|     }
439|     ctx.restore();
440|   }
441| 
442|   function draw() {
443|     ctx.clearRect(0, 0, W, H);
444|     ctx.fillStyle = PALETTE.bg;
445|     ctx.fillRect(0, 0, W, H);
446| 
447|     if (state === "title") {
448|       drawTitle();
449|       hintEl.textContent = "";
450|       return;
451|     }
452| 
453|     const { bx, by, cellSize, size } = boardMetrics();
454| 
455|     // board backing plate
456|     drawPlate(bx - 6, by - 6, size + 12, size + 12, 14, "#ffffff22", "boardplate", false);
457|     drawPlate(bx - 4, by - 4, size + 8, size + 8, 12, PALETTE.bg, "boardbg", true);
458| 
459|     // grid cells
460|     for (let gy = 0; gy < GRID; gy++) {
461|       for (let gx = 0; gx < GRID; gx++) {
462|         const px = bx + gx * cellSize;
463|         const py = by + gy * cellSize;
464|         const k = key(gx, gy);
465|         const isExit = (gx === exitPos.x && gy === exitPos.y);
466|         if (hedges.has(k)) {
467|           drawHedge(px, py, cellSize, k);
468|         } else {
469|           const shade = ((gx + gy) % 2 === 0) ? PALETTE.bg : "#ecdfc4";
470|           drawPlate(px + 3, py + 3, cellSize - 6, cellSize - 6, 6, shade, "cell" + k, false);
471|         }
472|         if (isExit) {
473|           ctx.save();
474|           ctx.strokeStyle = PALETTE.highlight;
475|           ctx.lineWidth = 3;
476|           ctx.strokeRect(px + 5, py + 5, cellSize - 10, cellSize - 10);
477|           ctx.fillStyle = PALETTE.accent;
478|           ctx.font = "bold " + Math.floor(cellSize * 0.28) + "px sans-serif";
479|           ctx.textAlign = "center";
480|           ctx.textBaseline = "middle";
481|           ctx.fillText("🚪", px + cellSize / 2, py + cellSize / 2);
482|           ctx.restore();
483|         }
484|       }
485|     }
486| 
487|     // apples
488|     for (const a of apples) {
489|       if (a.collected) continue;
490|       const cx = bx + a.x * cellSize + cellSize / 2;
491|       const cy = by + a.y * cellSize + cellSize / 2;
492|       drawApple(cx, cy, cellSize * 0.5);
493|     }
494| 
495|     // hedgehog
496|     const hx = bx + hedgehog.x * cellSize + cellSize / 2;
497|     const hy = by + hedgehog.y * cellSize + cellSize / 2;
498|     drawHedgehog(hx, hy, cellSize * 0.42);
499| 
500|     // HUD
501|     drawHUD();
502| 
503|     if (state === "ended") {
504|       drawEndOverlay();
505|     }
506| 
507|     hintEl.textContent = state === "playing" ? "Glissez pour déplacer le hérisson" : "";
508|   }
509| 
510|   function drawHUD() {
511|     const padding = 10;
512|     const plateW = Math.min(W * 0.9, 420);
513|     const plateH = 54;
514|     const px = (W - plateW) / 2;
515|     const py = 8;
516|     drawPlate(px, py, plateW, plateH, 10, "#ffffff", "hud", true);
517|     ctx.fillStyle = PALETTE.accent;
518|     ctx.font = "bold 16px sans-serif";
519|     ctx.textAlign = "left";
520|     ctx.textBaseline = "middle";
521|     ctx.fillText("Niveau " + level, px + 14, py + plateH / 2);
522|     ctx.textAlign = "center";
523|     ctx.fillText("Score: " + score, px + plateW / 2, py + plateH / 2);
524|     ctx.textAlign = "right";
525|     ctx.fillText("Pas: " + stepsLeft, px + plateW - 14, py + plateH / 2);
526|   }
527| 
528|   function drawTitle() {
529|     const plateW = Math.min(W * 0.85, 500);
530|     const plateH = Math.min(H * 0.4, 260);
531|     const px = (W - plateW) / 2;
532|     const py = (H - plateH) / 2;
533|     drawPlate(px, py, plateW, plateH, 20, "#ffffff", "titleplate", true);
534| 
535|     ctx.fillStyle = PALETTE.accent;
536|     ctx.textAlign = "center";
537|     ctx.textBaseline = "middle";
538|     ctx.font = "bold " + Math.floor(Math.min(plateW, plateH) * 0.11) + "px sans-serif";
539|     wrapText("Le Labyrinthe du Hérisson", px + plateW / 2, py + plateH * 0.32, plateW * 0.85, Math.floor(plateW * 0.09));
540| 
541|     drawHedgehog(px + plateW / 2, py + plateH * 0.62, Math.min(plateW, plateH) * 0.12);
542| 
543|     ctx.font = "16px sans-serif";
544|     ctx.fillStyle = PALETTE.accent;
545|     ctx.fillText("Touchez ou appuyez sur Entrée pour jouer", px + plateW / 2, py + plateH * 0.88);
546|   }
547| 
548|   function drawEndOverlay() {
549|     ctx.save();
550|     ctx.fillStyle = "rgba(61,64,91,0.45)";
551|     ctx.fillRect(0, 0, W, H);
552|     ctx.restore();
553| 
554|     const plateW = Math.min(W * 0.8, 420);
555|     const plateH = Math.min(H * 0.3, 200);
556|     const px = (W - plateW) / 2;
557|     const py = (H - plateH) / 2;
558|     drawPlate(px, py, plateW, plateH, 18, "#ffffff", "endplate", true);
559| 
